
import subprocess
import plistlib
import base64

hex_str = "".replace("\n", "").replace(" ", "")
length_bytes = 720  # 要截取的字节数
hex_needed = length_bytes * 2  # 每字节2个hex字符
# 截取以62706c69 73743030开头 且指定长度的字符串
hex_str = hex_str[hex_str.find("62706c6973743030"):]
payload = hex_str[:hex_needed]
# 调用命令行将 hex 转成二进制 bplist
proc = subprocess.run(
    ["xxd", "-r", "-p", "-", "inv.bplist"],
    input=payload.encode(),
    check=True
)
print(f"写入 inv.bplist（{length_bytes} bytes）成功")
# 调用命令行将 bplist 转成 xml
proc = subprocess.run(
    ["plutil", "-convert", "xml1", "inv.bplist", "-o", "inv.xml"],
    check=True
)
print("转换 inv.xml 成功")

import xml.etree.ElementTree as ET
# 读取 xml 内容
tree = ET.parse("inv.xml")
root = tree.getroot()
for i, elem in enumerate(root.iter()):
    if elem.tag == "key" and elem.text == "bodyData":
        data_elem = list(root.iter())[i+1]  # 紧跟的 <data> 节点
        # 要输出将空格和换行符 和制表符 去掉的单行的字符串
        print("XML 中原始 Base64：", data_elem.text.strip().replace("\n", "").replace(" ", "").replace("\t", ""))
        
